class LLMAgent:
    def __init__(self, agent_id: int):
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.observed_actions = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is not None:
            actions = self.observed_actions.get(opponent)
            if actions:
                last_action = actions[-1]
                if self._is_defect(last_action):
                    return False
        return True

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        self.observed_actions.setdefault(donor_id, []).append(donor_action)
        self.observed_actions.setdefault(recipient_id, []).append(recipient_action)

    @staticmethod
    def _is_defect(action: str) -> bool:
        if action is None:
            return False
        if isinstance(action, bool):
            return not action
        if isinstance(action, str):
            a = action.strip().lower()
            return a in ("d", "defect")
        return False

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.last_action = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is not None:
            last = self.last_action.get(opponent)
            if last is not None and self._is_defect(last):
                return False
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self.last_action[donor_id] = donor_action
        self.last_action[recipient_id] = recipient_action

    @staticmethod
    def _is_defect(action: str) -> bool:
        if isinstance(action, str):
            return action.lower() in ("d", "defect", "defects", "false", "0", "no", "betray")
        return not bool(action)

class LLMAgent:
    def __init__(self, agent_id: int):
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self._cooperate_count = {}
        self._defect_count = {}

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        if opponent_id is None:
            return True

        coops = self._cooperate_count.get(opponent_id, 0)
        defects = self._defect_count.get(opponent_id, 0)

        if coops + defects == 0:
            return True

        return coops / (coops + defects) >= 0.5

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        if donor_action == "cooperate":
            self._cooperate_count[donor_id] = self._cooperate_count.get(donor_id, 0) + 1
        else:
            self._defect_count[donor_id] = self._defect_count.get(donor_id, 0) + 1

        if recipient_action == "cooperate":
            self._cooperate_count[recipient_id] = self._cooperate_count.get(recipient_id, 0) + 1
        else:
            self._defect_count[recipient_id] = self._defect_count.get(recipient_id, 0) + 1

class LLMAgent:
    def __init__(self, agent_id: int):
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self._last_action = {}

    def _to_bool(self, action: str) -> bool:
        if isinstance(action, bool):
            return action
        if action is None:
            return True
        return action.lower() in ('cooperate', 'coop', 'c', 'true', 'yes', '1')

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        return self._last_action.get(opponent, True)

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self._last_action[donor_id] = self._to_bool(donor_action)
        self._last_action[recipient_id] = self._to_bool(recipient_action)

