class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.images = {}

    def _is_coop(self, action: str) -> bool:
        if action is None:
            return False
        if isinstance(action, bool):
            return action
        return str(action).strip().upper().startswith("C")

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        return self.images.get(opp, 0) >= 0

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self.images[donor_id] = self.images.get(donor_id, 0) + (1 if self._is_coop(donor_action) else -1)
        self.images[recipient_id] = self.images.get(recipient_id, 0) + (1 if self._is_coop(recipient_action) else -1)

