class LLMAgent:
    def __init__(self, agent_id: int):
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.history = {}
        self.observed_defections = {}
        self.observed_cooperations = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        # Direct reciprocity: cooperate if the opponent has cooperated at least half the time
        if opp in self.history and self.history[opp]:
            hist = self.history[opp]
            cooperations = sum(1 for x in hist if x)
            return cooperations >= len(hist) / 2

        # Reputation-based decision: defect only if defections outweigh cooperations by more than one
        defections = self.observed_defections.get(opp, 0)
        cooperations = self.observed_cooperations.get(opp, 0)
        if defections > cooperations + 1:
            return False

        # Default to cooperation
        return True

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        def is_cooperation(action):
            if isinstance(action, str):
                return action.lower() in ('c', 'cooperate', 'coop', 'true', 'yes')
            return bool(action)

        donor_coop = is_cooperation(donor_action)
        recipient_coop = is_cooperation(recipient_action)

        if donor_id == self.agent_id:
            opp = recipient_id
            self.history.setdefault(opp, []).append(recipient_coop)
        elif recipient_id == self.agent_id:
            opp = donor_id
            self.history.setdefault(opp, []).append(donor_coop)
        else:
            if donor_coop:
                self.observed_cooperations[donor_id] = self.observed_cooperations.get(donor_id, 0) + 1
            else:
                self.observed_defections[donor_id] = self.observed_defections.get(donor_id, 0) + 1

            if recipient_coop:
                self.observed_cooperations[recipient_id] = self.observed_cooperations.get(recipient_id, 0) + 1
            else:
                self.observed_defections[recipient_id] = self.observed_defections.get(recipient_id, 0) + 1

