class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.last_action = {}
        self.defections = {}
        self.cooperations = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        # Direct tit-for-tat: defect if opponent defected against us last time.
        if self.last_action.get(opp, False):
            return False

        # Reputation-based: if the opponent has defected more than cooperated
        # in any interactions we observed, defect.
        d = self.defections.get(opp, 0)
        c = self.cooperations.get(opp, 0)
        if d + c > 0 and d > c:
            return False

        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Record observed behavior of all agents (excluding self).
        def record(agent_id: int, action) -> None:
            if agent_id == self.agent_id:
                return
            if self._is_defect(action):
                self.defections[agent_id] = self.defections.get(agent_id, 0) + 1
            else:
                self.cooperations[agent_id] = self.cooperations.get(agent_id, 0) + 1

        record(donor_id, donor_action)
        record(recipient_id, recipient_action)

        # Maintain direct interaction memory, as in the parent strategy.
        if recipient_id == self.agent_id and donor_id != self.agent_id:
            self.last_action[donor_id] = self._is_defect(donor_action)
        if donor_id == self.agent_id and recipient_id != self.agent_id:
            self.last_action[recipient_id] = self._is_defect(recipient_action)

    def _is_defect(self, action) -> bool:
        if isinstance(action, str):
            return action.lower() in ('d', 'defect')
        return action is False

