        if action is None:
            return False
        if isinstance(action, bool):
            return action
        return str(action).strip().upper().startswith("C")

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        return self.images.get(opp, 1) >= 0

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        decay = 0.9

        if donor_id == self.agent_id:
            old = self.images.get(recipient_id, 1)
            val = 1 if self._is_coop(recipient_action) else -2
            self.images[recipient_id] = old * decay + val

        elif recipient_id == self.agent_id:
            old = self.images.get(donor_id, 1)
            val = 1 if self._is_coop(donor_action) else -2
            self.images[donor_id] = old * decay + val

        else:
            # Third-party observations evaluate only the donor.
            old_donor = self.images.get(donor_id, 1)
            val_donor = 1 if self._is_coop(donor_action) else -2
            self.images[donor_id] = old_donor * decay + val_donor

